using NUnit.Framework;

[TestFixture]
public class BubbleSortTests
{
    [Test]
    public void BubbleSort_SortsAscending()
    {
        var nums = new[] { 35, 46, 10, 5, 0, -1, 2, 75 };
        BubbleSort(nums);
        Assert.That(nums, Is.EqualTo(new[] { -1, 0, 2, 5, 10, 35, 46, 75 }));
    }

    private void BubbleSort(int[] nums)
    {
        for (int pass = 0; pass < nums.Length - 1; pass++)
        {
            for (int j = 0; j < nums.Length - 1 - pass; j++)
            {
                if (nums[j] > nums[j + 1])
                    (nums[j], nums[j + 1]) = (nums[j + 1], nums[j]);
            }
        }
    }
}
